// Dipasaria identity: a snapper leaping out of a market basket, with a gold "senyum" beneath,
// and a two-tone Plus Jakarta Sans wordmark. Paths are generated by scripts/brand/build.cjs.
// Usage rules: docs/brand-guidelines.md.
import { EMBLEM, WORDMARK, TAGLINE, SEAL_RING } from "@/components/brand/paths";

export const BRAND_COLORS = { black: "#000000", cream: "#FAF8F4", parchment: "#EEE7DA", gold: "#EAB200", deep: "#C09200" } as const;

type Variant = "color" | "reversed" | "black" | "cream";
const V: Record<Variant, { basket: string; fish: string; eye: string | null; smile: string }> = {
  color: { basket: "#000000", fish: "#EAB200", eye: "#000000", smile: "#C09200" },
  reversed: { basket: "#FAF8F4", fish: "#EAB200", eye: "#000000", smile: "#EAB200" },
  black: { basket: "#000000", fish: "#000000", eye: null, smile: "#000000" },
  cream: { basket: "#FAF8F4", fish: "#FAF8F4", eye: null, smile: "#FAF8F4" },
};
const EYE_HOLE = `M${EMBLEM.eye.cx + EMBLEM.eye.r} ${EMBLEM.eye.cy}A${EMBLEM.eye.r} ${EMBLEM.eye.r} 0 1 0 ${EMBLEM.eye.cx - EMBLEM.eye.r} ${EMBLEM.eye.cy}A${EMBLEM.eye.r} ${EMBLEM.eye.r} 0 1 0 ${EMBLEM.eye.cx + EMBLEM.eye.r} ${EMBLEM.eye.cy}Z`;

/** The emblem as SVG children, in its 120 × 123 coordinate space. */
function EmblemShapes({ variant }: { variant: Variant }) {
  const v = V[variant];
  return (
    <>
      <g transform={EMBLEM.fishTransform} fill={v.fish}>
        <path fillRule="evenodd" d={v.eye ? EMBLEM.fish : EMBLEM.fish + EYE_HOLE} />
        <path d={EMBLEM.fin} />
        {v.eye && <circle cx={EMBLEM.eye.cx} cy={EMBLEM.eye.cy} r={EMBLEM.eye.r} fill={v.eye} />}
      </g>
      <path fillRule="evenodd" fill={v.basket} d={EMBLEM.basket} />
      <path d={EMBLEM.smile} fill="none" stroke={v.smile} strokeWidth={EMBLEM.smileWidth} strokeLinecap="round" />
    </>
  );
}

export function Emblem({ className = "h-10 w-10", variant = "color" }: { className?: string; variant?: Variant }) {
  return <svg viewBox={EMBLEM.viewBox} className={className} aria-hidden><EmblemShapes variant={variant} /></svg>;
}

/** App-icon style tile: black rounded square with the reversed emblem. */
export function LogoMark({ className = "h-8 w-8", tile = true }: { className?: string; tile?: boolean }) {
  if (!tile) return <Emblem className={className} />;
  const s = 46 / 123;
  return (
    <svg viewBox="0 0 64 64" className={className} aria-hidden>
      <rect width="64" height="64" rx="13" fill="#000" />
      <g transform={`translate(${32 - 60 * s} 9) scale(${s})`}><EmblemShapes variant="reversed" /></g>
    </svg>
  );
}

function Word({ dark }: { dark: boolean }) {
  return (
    <>
      <path fill={dark ? BRAND_COLORS.cream : BRAND_COLORS.black} d={WORDMARK.dipa} />
      <path fill={dark ? BRAND_COLORS.gold : BRAND_COLORS.deep} d={WORDMARK.saria} />
    </>
  );
}

function TagRow({ x, y, width, scale, dark, gap, ruleH }: { x: number; y: number; width: number; scale: number; dark: boolean; gap: number; ruleH: number }) {
  const tw = TAGLINE.width * scale;
  const rule = (width - tw) / 2 - gap;
  const mid = y - (TAGLINE.cap * scale) / 2;
  const ruleFill = dark ? BRAND_COLORS.gold : BRAND_COLORS.deep;
  return (
    <>
      <rect x={x} y={mid - ruleH / 2} width={rule} height={ruleH} fill={ruleFill} />
      <rect x={x + width - rule} y={mid - ruleH / 2} width={rule} height={ruleH} fill={ruleFill} />
      <g transform={`translate(${x + rule + gap} ${y}) scale(${scale})`}><path fill={dark ? BRAND_COLORS.cream : BRAND_COLORS.black} d={TAGLINE.d} /></g>
    </>
  );
}

const HEIGHT = { sm: "h-9", md: "h-11", lg: "h-16", xl: "h-24" } as const;

/**
 * Horizontal lockup (header, documents) or stacked lockup (footer, packaging, hero moments).
 * `dark` = for black backgrounds. `tagline` adds "— SEGAR & TERPILIH —".
 */
export function Logo({ dark = false, size = "md", tagline = false, stacked = false, className }: { dark?: boolean; size?: keyof typeof HEIGHT; tagline?: boolean; stacked?: boolean; className?: string; descriptor?: boolean }) {
  const cls = className ?? `${HEIGHT[size]} w-auto`;
  if (stacked) {
    const W = 460, es = 1.75, wx = (W - WORDMARK.width) / 2, base = 123 * es + 26 + WORDMARK.cap, ty = base + WORDMARK.desc + 40;
    const H = tagline ? ty + 6 : base + WORDMARK.desc + 4;
    return (
      <svg viewBox={`0 0 ${W} ${H}`} className={cls} role="img" aria-label={tagline ? "Dipasaria — Segar & terpilih" : "Dipasaria"}>
        <g transform={`translate(${(W - 120 * es) / 2} 0) scale(${es})`}><EmblemShapes variant={dark ? "reversed" : "color"} /></g>
        <g transform={`translate(${wx} ${base})`}><Word dark={dark} /></g>
        {tagline && <TagRow x={wx} y={ty} width={WORDMARK.width} scale={1.45} dark={dark} gap={16} ruleH={3} />}
      </svg>
    );
  }
  const s = 52 / WORDMARK.cap, wx = 136, ww = WORDMARK.width * s, base = tagline ? 74 : 88;
  const W = Math.ceil(wx + ww + 2);
  return (
    <svg viewBox={`0 0 ${W} 123`} className={cls} role="img" aria-label={tagline ? "Dipasaria — Segar & terpilih" : "Dipasaria"}>
      <EmblemShapes variant={dark ? "reversed" : "color"} />
      <g transform={`translate(${wx} ${base}) scale(${s})`}><Word dark={dark} /></g>
      {tagline && <TagRow x={wx} y={108} width={ww} scale={(ww * 0.62) / TAGLINE.width} dark={dark} gap={10} ruleH={2} />}
    </svg>
  );
}

/** "— SEGAR & TERPILIH —" as live text, for use beside headings and on bands. */
export function Tagline({ dark = false, className = "" }: { dark?: boolean; className?: string }) {
  return (
    <span className={`inline-flex items-center gap-3 font-sans text-[11px] font-bold uppercase tracking-[0.32em] ${dark ? "text-sand-50" : "text-ink"} ${className}`}>
      <span className={`h-px w-8 ${dark ? "bg-coral-500" : "bg-coral-600"}`} />Segar &amp; terpilih<span className={`h-px w-8 ${dark ? "bg-coral-500" : "bg-coral-600"}`} />
    </span>
  );
}

/** Provenance seal for the footer, packaging stickers and quality marks. */
export function Seal({ className = "h-40 w-40", color = "#EAB200", fill = "#000" }: { className?: string; color?: string; fill?: string; eye?: string }) {
  const mono = { basket: color, fish: color, eye: null, smile: color };
  return (
    <svg viewBox="0 0 200 200" className={className} role="img" aria-label="Dipasaria · Segar & terpilih · Muara Baru, Jakarta">
      <circle cx="100" cy="100" r="96" fill={fill} />
      <circle cx="100" cy="100" r="92" fill="none" stroke={color} strokeWidth="1.6" />
      <circle cx="100" cy="100" r="86" fill="none" stroke={color} strokeWidth="0.6" />
      <circle cx="100" cy="100" r="58" fill="none" stroke={color} strokeWidth="0.8" />
      <g fill={color} dangerouslySetInnerHTML={{ __html: SEAL_RING }} />
      <g transform="translate(58 55) scale(0.7)">
        <g transform={EMBLEM.fishTransform} fill={mono.fish}><path fillRule="evenodd" d={EMBLEM.fish + EYE_HOLE} /><path d={EMBLEM.fin} /></g>
        <path fillRule="evenodd" fill={mono.basket} d={EMBLEM.basket} />
        <path d={EMBLEM.smile} fill="none" stroke={mono.smile} strokeWidth={EMBLEM.smileWidth} strokeLinecap="round" />
      </g>
    </svg>
  );
}
